
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, department = EXCLUDED.department, squad = EXCLUDED.squad, responsibilities = EXCLUDED.responsibilities;

-- Hunter LinkedIn: schema completo
UPDATE public.agents_catalog
SET 
  tagline = 'Prospecção automatizada no LinkedIn com IA',
  description = 'Encontra leads qualificados no LinkedIn, gera icebreakers personalizados com IA e envia convites de conexão automaticamente.',
  config_schema = '[
    {"key":"target_audience","label":"Público-alvo","type":"textarea","required":true,"placeholder":"Ex: CTOs e VPs de Engenharia em SaaS B2B com 50-500 funcionários","help":"Descreva o ICP que o agente deve buscar"},
    {"key":"job_titles","label":"Cargos","type":"tags","placeholder":"CTO, VP Engineering, Head of Tech","help":"Cargos a buscar (separe por enter)"},
    {"key":"location","label":"Localização","type":"text","placeholder":"Brasil, São Paulo","help":"País, estado ou cidade"},
    {"key":"linkedin_cookie","label":"Cookie LinkedIn (li_at)","type":"password","required":true,"help":"Cookie de sessão do seu LinkedIn. Configure em Hunter > Configurações."},
    {"key":"daily_limit","label":"Limite diário de convites","type":"slider","min":10,"max":50,"default":20,"help":"Recomendado: 20 para evitar bloqueio"},
    {"key":"icebreaker_template","label":"Template de icebreaker","type":"textarea","placeholder":"Olá {nome}, vi que você é {cargo} na {empresa}...","help":"Use {nome}, {cargo}, {empresa} como variáveis"}
  ]'::jsonb,
  tier = 'pro',
  monthly_price_cents = 99700
WHERE slug = 'hunter_linkedin';
